shell_commands:
/bin/zsh -lc "cat > scripts/lore-multiple-anchors.test.ts <<'EOF'
import {execFileSync} from 'node:child_process';
import {mkdtempSync, mkdirSync, realpathSync, rmSync, writeFileSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, resolve} from 'node:path';

// specs/lore-test-descriptors/spec.md#2
it('associates each test with its own preceding stamp', () => {
  const root = realpathSync(mkdtempSync(join(tmpdir(), 'lore-list-')));
  try {
    const bin = join(root, 'bin');
    mkdirSync(bin);
    const file = join(root, 'sample.test.ts');
    writeFileSync(file, '// specs/example/spec.md#1\\nit(\"first\", () => {});\\n// specs/example/spec.md#2\\nit(\"second\", () => {});\\n');
    const report = JSON.stringify({testResults: [{name: file, assertionResults: [
      {fullName: 'first', location: {line: 2, column: 1}},
      {fullName: 'second', location: {line: 4, column: 1}},
    ]}]});
    writeFileSync(join(bin, 'npx'), "'`#!/bin/sh'"\\nfor arg in \""'$@"; do'"\\n  case \""'$arg" in --outputFile=*) printf '"'%s' '"'${report}'"' > \""'${'"'"'$'"'}{arg#--outputFile=}\";; esac\\ndone\\n"'`, {mode: 0o755});
    const output = execFileSync('"'node', [resolve('scripts/lore-list-tests.mjs')], {
      cwd: root, env: {...process.env, PATH: "'`${bin}:${process.env.PATH ?? '"''}"'`}, encoding: '"'utf8',
    });
    expect(JSON.parse(output)).toEqual([
      {id: 'sample.test.ts::first', name: 'first', file: 'sample.test.ts', spec: 'specs/example/spec.md#1'},
      {id: 'sample.test.ts::second', name: 'second', file: 'sample.test.ts', spec: 'specs/example/spec.md#2'},
    ]);
  } finally {
    rmSync(root, {recursive: true, force: true});
  }
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath scripts/lore-multiple-anchors.test.ts"
